/** Trả chuỗi <svg> cho tên 'tên-bộ/tên-icon'; class CSS tuỳ chọn. */
export function icon(name, cls = 'ic') {
  const raw = ICONS[name];
  if (!raw) return '';
  return raw.replace('<svg ', '<svg class="' + cls + '" aria-hidden="true" ');
}
